+HcclResult ParseNewSelector()
+{
+    std::string useNewSelectorEnv = GetEnv("HCCL_USE_NEW_SELECTOR");
+    if (useNewSelectorEnv == "EmptyString") {
+        HCCL_INFO("HCCL_USE_NEW_SELECTOR set by default to [0]");
